package lk.ac.sliit.ridelink.driver.infrastructure.security;
import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import lk.ac.sliit.ridelink.driver.infrastructure.configuration.DriverProperties; import org.springframework.stereotype.Component; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.Date;
@Component public class InternalServiceTokenProvider { private final DriverProperties p; public InternalServiceTokenProvider(DriverProperties p){this.p=p;} public String token(){Instant now=Instant.now();return Jwts.builder().subject("driver-vehicle-service").issuer(p.jwtIssuer()).claim("role","SERVICE").claim("token_type","SERVICE").issuedAt(Date.from(now)).expiration(Date.from(now.plusMillis(p.serviceTokenExpirationMs()))).signWith(Keys.hmacShaKeyFor(p.jwtSecret().getBytes(StandardCharsets.UTF_8))).compact();} }
